if(location.protocol!=='file:'&&new URLSearchParams(location.search).has('sheets'))view='products';
const productsBeforeSheets=products;
products=function(){productsBeforeSheets();const first=$('.panel',$('#view'));first.insertAdjacentHTML('beforebegin','<div class="panel" id="sheets-panel"><h3>Google Sheets products</h3><p>Loading sheet connection...</p></div>');drawProductSheet()};
async function drawProductSheet(){try{const s=await api('/sheets');if(view!=='products'||!$('#sheets-panel'))return;const currentForm=$('#sheet-settings');if(currentForm?.contains(document.activeElement))return;const cfg=s.settings;$('#sheets-panel').innerHTML=`<div class="panel-head"><h3>Google Sheets products</h3><span class="pill">${s.connected?'Google connected':'Not connected'}</span></div><p>Read product rows from your private Google Sheet into this product list. Updates here do not write back to Google.</p>${!s.configured?'<div class="note warning">The server administrator must configure Google OAuth and token encryption first. See GOOGLE-SHEETS.md.</div>':''}${s.workerEnabled===false?'<div class="note warning">Background sheet updates are disabled on this server. Manual preview and import remain available.</div>':''}${s.error?'<div class="note warning">'+esc(s.error)+'</div>':''}${new URLSearchParams(location.search).get('sheets')==='error'?'<div class="note warning">Google authorization did not complete. Try connecting again and grant read-only Sheets access.</div>':''}<p>Last update: ${s.lastSync?date(s.lastSync):'Not synced yet'}</p><div class="actions"><button class="btn secondary" id="google-sheet-connect" ${!s.configured?'disabled':''}>${s.connected?'Reconnect Google account':'Connect Google account'}</button>${s.connected?'<button class="btn secondary" id="google-sheet-disconnect">Disconnect</button>':''}<button class="btn secondary" id="google-sheet-template">Download sheet template</button></div>${s.connected?`<form id="sheet-settings"><div class="two-fields">${input('spreadsheet','Google spreadsheet URL or ID',cfg.spreadsheetId||'','text','required')}${input('tab','Sheet tab name',cfg.tab||'Products','text','required maxlength="100"')}</div><label class="check"><input type="checkbox" name="automatic" ${cfg.automatic?'checked':''}>Update product details and prices automatically about every 5 minutes</label><label class="check"><input type="checkbox" name="replaceStock">Also replace existing available stock during this manual import</label><p class="hint">Automatic updates preserve existing stock. New products use the sheet stock. Only choose stock replacement when the sheet contains your current sellable quantities, including existing orders.</p><div class="actions"><button class="btn secondary">Save sheet settings</button><button type="button" class="btn" id="preview-sheet">Preview product update</button></div></form>`:''}<div class="note">Required columns: <b>sku, name, unit, price, stock</b>. Optional: <b>brand, lowStock</b>. Keep each SKU unique and stable. Rows missing from the sheet are kept in your store. Existing manual products are kept separate.</div>`;
 $('#google-sheet-template').onclick=()=>csv('google-sheet-products',[{sku:'RICE-1KG',name:'Basmati rice',brand:'Example',unit:'1 kg',price:120,stock:25,lowStock:5}],['sku','name','brand','unit','price','stock','lowStock']);
 $('#google-sheet-connect').onclick=async e=>{e.target.disabled=true;try{const c=await api('/sheets/connect','POST',{});location.assign(c.url)}catch(err){toast(err.message);e.target.disabled=false}};
 if(!s.connected)return;$('#google-sheet-disconnect').onclick=async()=>{if(!confirm('Stop Google Sheets updates for this store? Imported products stay saved.'))return;try{await api('/sheets/disconnect','POST',{});await drawProductSheet()}catch(e){toast(e.message)}};
 const saveConfig=async()=>{const b=Object.fromEntries(new FormData($('#sheet-settings')));await api('/sheets/config','POST',{spreadsheet:b.spreadsheet,tab:b.tab,automatic:b.automatic==='on'});return b.replaceStock==='on'};
 $('#sheet-settings').onsubmit=async e=>{e.preventDefault();try{await saveConfig();await drawProductSheet();toast('Sheet settings saved')}catch(e){toast(e.message)}};
 $('#preview-sheet').onclick=async e=>{e.target.disabled=true;try{const replaceStock=await saveConfig(),p=await api('/sheets/preview','POST',{replaceStock});modal(`<h2>Preview sheet update</h2><p>${p.added} new products · ${p.updated} existing sheet products · ${p.total} sheet rows</p><div class="note ${replaceStock?'warning':''}">${replaceStock?'Existing stock quantities WILL be replaced by these sheet values.':'Existing stock is preserved. Names, brands, units, prices and low-stock thresholds update.'}</div>${table(['SKU','PRODUCT','UNIT','PRICE','SHEET STOCK'],p.rows.map(r=>row([esc(r.sku),esc(r.name),esc(r.unit),money(r.price),esc(r.stock)])))}<p class="hint">Showing the first ${p.rows.length} rows. All ${p.total} validated rows will be applied. Preview expires in 5 minutes.</p><form id="edit-form">${formEnd('Apply product update')}`);bindForm(async()=>{await api('/sheets/apply','POST',{previewId:p.id});store=await api('/store');products();toast('Products updated from Google Sheets')})}catch(err){toast(err.message)}finally{if($('#preview-sheet'))$('#preview-sheet').disabled=false}};
 }catch(e){if($('#sheets-panel'))$('#sheets-panel').textContent=e.message}}
setInterval(async()=>{if(!me||me.role!=='client'||view!=='products'||document.visibilityState==='hidden'||$('#modal').open)return;try{const fresh=await api('/store');if(fresh.rev!==store.rev){store=fresh;productRows()}await drawProductSheet()}catch{}},60000);
